=== RecognisedRisk ===
/**
 * A risk the MHPCO recognises on a single insured item, and the surcharge rate it carries.
 *
 * The office's risk catalogue: each entry names one hazard, says when an item carries it,
 * and at what rate. Revising a threshold or a rate is a change to one entry; recognising
 * a new hazard is a new entry.
 */
public enum RecognisedRisk {

    CURSE(0.50) {
        @Override
        boolean isCarriedBy(Item item) {
            return item.cursed();
        }
    },

    HIGH_ENCHANTMENT(0.30) {
        /** The enchantment level from which the office surcharges a premium for risk. */
        private static final int SURCHARGED_ENCHANTMENT_LEVEL = 5;

        @Override
        boolean isCarriedBy(Item item) {
            return item.enchantment() >= SURCHARGED_ENCHANTMENT_LEVEL;
        }
    };

    private final double rate;

    RecognisedRisk(double rate) {
        this.rate = rate;
    }

    abstract boolean isCarriedBy(Item item);

    double rate() {
        return rate;
    }
}
=== OfficesFavour ===
/**
 * Rounding "in the MHPCO's favour": whichever way the fraction falls, the office keeps it.
 *
 * The favour is one rule with two directions, because the direction depends on which way the
 * money flows. Money the office receives is rounded up; money the office pays out is rounded
 * down. Stating both here keeps them from drifting apart.
 */
public final class OfficesFavour {

    private OfficesFavour() {
    }

    /** An amount the customer pays the office, rounded up to whole G. */
    public static int onAmountReceived(double amount) {
        return (int) Math.ceil(amount);
    }

    /** An amount the office pays the customer, rounded down to whole G. */
    public static int onAmountPaidOut(double amount) {
        return (int) Math.floor(amount);
    }
}

import java.util.List;

/**
 * The items a policy covers, asked which of them a reported damage concerns.
 *
 * A damage report names only a type, so the office has to look the damaged item up among
 * the items the policy insures before any clause can be applied to it. That lookup is the
 * policy's knowledge of its own cover, not part of working out an amount, and it is where
 * the office's objections to a damage report outside the cover belong.
 */
public class InsuredItems {

    private final List<Item> items;

    public InsuredItems(List<Item> items) {
        this.items = items;
    }

    public Item coveringItemFor(Damage damage) {
        for (Item item : items) {
            if (item.type().equals(damage.itemType())) {
                return item;
            }
        }
        throw new ClaimOfficeException("The policy does not cover an item of type " + damage.itemType());
    }
}
/**
 * An item offered for insurance, as described in the scenario.
 *
 * Components such as runes carry no material and no enchantment level.
 */
public record Item(String type, String material, int enchantment, boolean cursed) {

    public Item(String type) {
        this(type, null, 0, false);
    }
}
